insert into public.ejercicio (id,nombre_es,nombre_en,musculos_principales,musculos_secundarios,equipo,categoria,tipo_registro,imagenes,instrucciones,fuente,licencia) values
('Arm_Circles','Círculos de brazos','Arm Circles',ARRAY['shoulders']::text[],ARRAY['traps']::text[],NULL,'stretching','check',ARRAY['Arm_Circles/0.jpg','Arm_Circles/1.jpg']::text[],ARRAY['Stand up and extend your arms straight out by the sides. The arms should be parallel to the floor and perpendicular (90-degree angle) to your torso. This will be your starting position.','Slowly start to make circles of about 1 foot in diameter with each outstretched arm. Breathe normally as you perform the movement.','Continue the circular motion of the outstretched arms for about ten seconds. Then reverse the movement, going the opposite direction.']::text[],'Free Exercise DB','Unlicense (dominio público)'),
('Shoulder_Circles','Círculos de hombros','Shoulder Circles',ARRAY['shoulders']::text[],ARRAY['traps']::text[],NULL,'stretching','check',ARRAY['Shoulder_Circles/0.jpg','Shoulder_Circles/1.jpg']::text[],ARRAY['With shoulders relaxed and arms resting loosely at your sides (or in your lap if you''re seated), gently roll your shoulders forward, up, back, and down.','Reverse direction. You can do this exercise alternating shoulders or both at the same time.']::text[],'Free Exercise DB','Unlicense (dominio público)'),
('Barbell_Bench_Press_-_Medium_Grip','Press de banca plano','Barbell Bench Press - Medium Grip',ARRAY['chest']::text[],ARRAY['shoulders','triceps']::text[],'barbell','strength','reps',ARRAY['Barbell_Bench_Press_-_Medium_Grip/0.jpg','Barbell_Bench_Press_-_Medium_Grip/1.jpg']::text[],ARRAY['Lie back on a flat bench. Using a medium width grip (a grip that creates a 90-degree angle in the middle of the movement between the forearms and the upper arms), lift the bar from the rack and hold it straight over you with your arms locked. This will be your starting position.','From the starting position, breathe in and begin coming down slowly until the bar touches your middle chest.','After a brief pause, push the bar back to the starting position as you breathe out. Focus on pushing the bar using your chest muscles. Lock your arms and squeeze your chest in the contracted position at the top of the motion, hold for a second and then start coming down slowly again. Tip: Ideally, lowering the weight should take about twice as long as raising it.','Repeat the movement for the prescribed amount of repetitions.','When you are done, place the bar back in the rack.']::text[],'Free Exercise DB','Unlicense (dominio público)'),
('Barbell_Incline_Bench_Press_-_Medium_Grip','Press inclinado con barra','Barbell Incline Bench Press - Medium Grip',ARRAY['chest']::text[],ARRAY['shoulders','triceps']::text[],'barbell','strength','reps',ARRAY['Barbell_Incline_Bench_Press_-_Medium_Grip/0.jpg','Barbell_Incline_Bench_Press_-_Medium_Grip/1.jpg']::text[],ARRAY['Lie back on an incline bench. Using a medium-width grip (a grip that creates a 90-degree angle in the middle of the movement between the forearms and the upper arms), lift the bar from the rack and hold it straight over you with your arms locked. This will be your starting position.','As you breathe in, come down slowly until you feel the bar on you upper chest.','After a second pause, bring the bar back to the starting position as you breathe out and push the bar using your chest muscles. Lock your arms in the contracted position, squeeze your chest, hold for a second and then start coming down slowly again. Tip: it should take at least twice as long to go down than to come up.','Repeat the movement for the prescribed amount of repetitions.','When you are done, place the bar back in the rack.']::text[],'Free Exercise DB','Unlicense (dominio público)'),
('Dumbbell_Flyes','Aperturas con mancuernas','Dumbbell Flyes',ARRAY['chest']::text[],'{}'::text[],'dumbbell','strength','reps',ARRAY['Dumbbell_Flyes/0.jpg','Dumbbell_Flyes/1.jpg']::text[],ARRAY['Lie down on a flat bench with a dumbbell on each hand resting on top of your thighs. The palms of your hand will be facing each other.','Then using your thighs to help raise the dumbbells, lift the dumbbells one at a time so you can hold them in front of you at shoulder width with the palms of your hands facing each other. Raise the dumbbells up like you''re pressing them, but stop and hold just before you lock out. This will be your starting position.','With a slight bend on your elbows in order to prevent stress at the biceps tendon, lower your arms out at both sides in a wide arc until you feel a stretch on your chest. Breathe in as you perform this portion of the movement. Tip: Keep in mind that throughout the movement, the arms should remain stationary; the movement should only occur at the shoulder joint.','Return your arms back to the starting position as you squeeze your chest muscles and breathe out. Tip: Make sure to use the same arc of motion used to lower the weights.','Hold for a second at the contracted position and repeat the movement for the prescribed amount of repetitions.']::text[],'Free Exercise DB','Unlicense (dominio público)'),
('Decline_Barbell_Bench_Press','Press declinado con barra','Decline Barbell Bench Press',ARRAY['chest']::text[],ARRAY['shoulders','triceps']::text[],'barbell','strength','reps',ARRAY['Decline_Barbell_Bench_Press/0.jpg','Decline_Barbell_Bench_Press/1.jpg']::text[],ARRAY['Secure your legs at the end of the decline bench and slowly lay down on the bench.','Using a medium width grip (a grip that creates a 90-degree angle in the middle of the movement between the forearms and the upper arms), lift the bar from the rack and hold it straight over you with your arms locked. The arms should be perpendicular to the floor. This will be your starting position. Tip: In order to protect your rotator cuff, it is best if you have a spotter help you lift the barbell off the rack.','As you breathe in, come down slowly until you feel the bar on your lower chest.','After a second pause, bring the bar back to the starting position as you breathe out and push the bar using your chest muscles. Lock your arms and squeeze your chest in the contracted position, hold for a second and then start coming down slowly again. Tip: It should take at least twice as long to go down than to come up).','Repeat the movement for the prescribed amount of repetitions.','When you are done, place the bar back in the rack.']::text[],'Free Exercise DB','Unlicense (dominio público)'),
('Triceps_Pushdown','Extensión de tríceps en polea','Triceps Pushdown',ARRAY['triceps']::text[],'{}'::text[],'cable','strength','reps',ARRAY['Triceps_Pushdown/0.jpg','Triceps_Pushdown/1.jpg']::text[],ARRAY['Attach a straight or angled bar to a high pulley and grab with an overhand grip (palms facing down) at shoulder width.','Standing upright with the torso straight and a very small inclination forward, bring the upper arms close to your body and perpendicular to the floor. The forearms should be pointing up towards the pulley as they hold the bar. This is your starting position.','Using the triceps, bring the bar down until it touches the front of your thighs and the arms are fully extended perpendicular to the floor. The upper arms should always remain stationary next to your torso and only the forearms should move. Exhale as you perform this movement.','After a second hold at the contracted position, bring the bar slowly up to the starting point. Breathe in as you perform this step.','Repeat for the recommended amount of repetitions.']::text[],'Free Exercise DB','Unlicense (dominio público)'),
('Leg_Extensions','Extensión de pierna en máquina','Leg Extensions',ARRAY['quadriceps']::text[],'{}'::text[],'machine','strength','reps',ARRAY['Leg_Extensions/0.jpg','Leg_Extensions/1.jpg']::text[],ARRAY['For this exercise you will need to use a leg extension machine. First choose your weight and sit on the machine with your legs under the pad (feet pointed forward) and the hands holding the side bars. This will be your starting position. Tip: You will need to adjust the pad so that it falls on top of your lower leg (just above your feet). Also, make sure that your legs form a 90-degree angle between the lower and upper leg. If the angle is less than 90-degrees then that means the knee is over the toes which in turn creates undue stress at the knee joint. If the machine is designed that way, either look for another machine or just make sure that when you start executing the exercise you stop going down once you hit the 90-degree angle.','Using your quadriceps, extend your legs to the maximum as you exhale. Ensure that the rest of the body remains stationary on the seat. Pause a second on the contracted position.','Slowly lower the weight back to the original position as you inhale, ensuring that you do not go past the 90-degree angle limit.','Repeat for the recommended amount of times.']::text[],'Free Exercise DB','Unlicense (dominio público)'),
('Crunches','Abdominales crunch','Crunches',ARRAY['abdominals']::text[],'{}'::text[],'body only','strength','reps',ARRAY['Crunches/0.jpg','Crunches/1.jpg']::text[],ARRAY['Lie flat on your back with your feet flat on the ground, or resting on a bench with your knees bent at a 90 degree angle. If you are resting your feet on a bench, place them three to four inches apart and point your toes inward so they touch.','Now place your hands lightly on either side of your head keeping your elbows in. Tip: Don''t lock your fingers behind your head.','While pushing the small of your back down in the floor to better isolate your abdominal muscles, begin to roll your shoulders off the floor.','Continue to push down as hard as you can with your lower back as you contract your abdominals and exhale. Your shoulders should come up off the floor only about four inches, and your lower back should remain on the floor. At the top of the movement, contract your abdominals hard and keep the contraction for a second. Tip: Focus on slow, controlled movement - don''t cheat yourself by using momentum.','After the one second contraction, begin to come down slowly again to the starting position as you inhale.','Repeat for the recommended amount of repetitions.']::text[],'Free Exercise DB','Unlicense (dominio público)'),
('Chest_And_Front_Of_Shoulder_Stretch','Estiramiento de pecho y hombro','Chest And Front Of Shoulder Stretch',ARRAY['chest']::text[],ARRAY['shoulders']::text[],'other','stretching','check',ARRAY['Chest_And_Front_Of_Shoulder_Stretch/0.jpg','Chest_And_Front_Of_Shoulder_Stretch/1.jpg']::text[],ARRAY['Start off by standing with your legs together, holding a bodybar or a broomstick.','Take a slightly wider than shoulder width grip on the pole and hold it in front of you with your palms facing down.','Carefully lift the pole up and behind your head.']::text[],'Free Exercise DB','Unlicense (dominio público)'),
('Triceps_Stretch','Estiramiento de tríceps','Triceps Stretch',ARRAY['triceps']::text[],ARRAY['lats']::text[],NULL,'stretching','check',ARRAY['Triceps_Stretch/0.jpg','Triceps_Stretch/1.jpg']::text[],ARRAY['Reach your hand behind your head, grasp your elbow and gently pull. Hold for 10 to 20 seconds, then switch sides.']::text[],'Free Exercise DB','Unlicense (dominio público)'),
('Quad_Stretch','Estiramiento de cuádriceps','Quad Stretch',ARRAY['quadriceps']::text[],'{}'::text[],'other','stretching','check',ARRAY['Quad_Stretch/0.jpg','Quad_Stretch/1.jpg']::text[],ARRAY['Lay on your side. Loop a belt, rope, or band around your top foot. Flex the knee and extend your hip, attempting to touch your glutes with your foot, and holding the belt with your hands. This will be your starting position.','With the belt being held over the shoulder or overhead, gently pull to increase the stretch in the quadriceps. Hold for 10-20 seconds, and then switch sides.']::text[],'Free Exercise DB','Unlicense (dominio público)'),
('Cat_Stretch','Gato (movilidad de columna)','Cat Stretch',ARRAY['lower back']::text[],ARRAY['middle back','traps']::text[],NULL,'stretching','check',ARRAY['Cat_Stretch/0.jpg','Cat_Stretch/1.jpg']::text[],ARRAY['Position yourself on the floor on your hands and knees.','Pull your belly in and round your spine, lower back, shoulders, and neck, letting your head drop.','Hold for 15 seconds.']::text[],'Free Exercise DB','Unlicense (dominio público)'),
('Wide-Grip_Lat_Pulldown','Jalón al pecho, agarre abierto','Wide-Grip Lat Pulldown',ARRAY['lats']::text[],ARRAY['biceps','middle back','shoulders']::text[],'cable','strength','reps',ARRAY['Wide-Grip_Lat_Pulldown/0.jpg','Wide-Grip_Lat_Pulldown/1.jpg']::text[],ARRAY['Sit down on a pull-down machine with a wide bar attached to the top pulley. Make sure that you adjust the knee pad of the machine to fit your height. These pads will prevent your body from being raised by the resistance attached to the bar.','Grab the bar with the palms facing forward using the prescribed grip. Note on grips: For a wide grip, your hands need to be spaced out at a distance wider than shoulder width. For a medium grip, your hands need to be spaced out at a distance equal to your shoulder width and for a close grip at a distance smaller than your shoulder width.','As you have both arms extended in front of you holding the bar at the chosen grip width, bring your torso back around 30 degrees or so while creating a curvature on your lower back and sticking your chest out. This is your starting position.','As you breathe out, bring the bar down until it touches your upper chest by drawing the shoulders and the upper arms down and back. Tip: Concentrate on squeezing the back muscles once you reach the full contracted position. The upper torso should remain stationary and only the arms should move. The forearms should do no other work except for holding the bar; therefore do not try to pull down the bar using the forearms.','After a second at the contracted position squeezing your shoulder blades together, slowly raise the bar back to the starting position when your arms are fully extended and the lats are fully stretched. Inhale during this portion of the movement.','Repeat this motion for the prescribed amount of repetitions.']::text[],'Free Exercise DB','Unlicense (dominio público)'),
('Close-Grip_Front_Lat_Pulldown','Jalón al pecho, agarre cerrado','Close-Grip Front Lat Pulldown',ARRAY['lats']::text[],ARRAY['biceps','middle back','shoulders']::text[],'cable','strength','reps',ARRAY['Close-Grip_Front_Lat_Pulldown/0.jpg','Close-Grip_Front_Lat_Pulldown/1.jpg']::text[],ARRAY['Sit down on a pull-down machine with a wide bar attached to the top pulley. Make sure that you adjust the knee pad of the machine to fit your height. These pads will prevent your body from being raised by the resistance attached to the bar.','Grab the bar with the palms facing forward using the prescribed grip. Note on grips: For a wide grip, your hands need to be spaced out at a distance wider than your shoulder width. For a medium grip, your hands need to be spaced out at a distance equal to your shoulder width and for a close grip at a distance smaller than your shoulder width.','As you have both arms extended in front of you - while holding the bar at the chosen grip width - bring your torso back around 30 degrees or so while creating a curvature on your lower back and sticking your chest out. This is your starting position.','As you breathe out, bring the bar down until it touches your upper chest by drawing the shoulders and the upper arms down and back. Tip: Concentrate on squeezing the back muscles once you reach the full contracted position. The upper torso should remain stationary (only the arms should move). The forearms should do no other work except for holding the bar; therefore do not try to pull the bar down using the forearms.','After a second in the contracted position, while squeezing your shoulder blades together, slowly raise the bar back to the starting position when your arms are fully extended and the lats are fully stretched. Inhale during this portion of the movement.','6. Repeat this motion for the prescribed amount of repetitions.']::text[],'Free Exercise DB','Unlicense (dominio público)'),
('Straight-Arm_Dumbbell_Pullover','Pullover con mancuerna','Straight-Arm Dumbbell Pullover',ARRAY['chest']::text[],ARRAY['lats','shoulders','triceps']::text[],'dumbbell','strength','reps',ARRAY['Straight-Arm_Dumbbell_Pullover/0.jpg','Straight-Arm_Dumbbell_Pullover/1.jpg']::text[],ARRAY['Place a dumbbell standing up on a flat bench.','Ensuring that the dumbbell stays securely placed at the top of the bench, lie perpendicular to the bench (torso across it as in forming a cross) with only your shoulders lying on the surface. Hips should be below the bench and legs bent with feet firmly on the floor. The head will be off the bench as well.','Grasp the dumbbell with both hands and hold it straight over your chest at arms length. Both palms should be pressing against the underside one of the sides of the dumbbell. This will be your starting position.
